    c0 = min(c for r, c in cells)
    c1 = max(c for r, c in cells)

    for r in range(r0, r1 + 1):
        for step, c in ((-1, c0 - 1), (1, c1 + 1)):
            while 0 <= c < w and grid[r][c] == 0:
                out[r][c] = 2
                c += step

    for c in range(c0, c1 + 1):
        for step, r in ((-1, r0 - 1), (1, r1 + 1)):
            while 0 <= r < h and grid[r][c] == 0:
                out[r][c] = 2
